import type { MetadataRoute } from "next";
import { getLocale, getTranslations } from "next-intl/server";
import { brand } from "@/config/brand";
import { localeInfo } from "@/i18n/locales";

/**
 * Web app manifest (served at /manifest.webmanifest). Icons are generated by scripts/generate-pwa-icons.mjs.
 * Description, shortcuts, lang and dir follow the visitor's language at install time.
 */
export default async function manifest(): Promise<MetadataRoute.Manifest> {
  const [locale, t] = await Promise.all([getLocale(), getTranslations("manifest")]);
  const info = localeInfo(locale);
  return {
    id: "/",
    name: brand.name,
    short_name: brand.name,
    description: t("description"),
    start_url: "/?source=pwa",
    scope: "/",
    display: "standalone",
    display_override: ["standalone", "minimal-ui"],
    orientation: "portrait",
    background_color: "#0b0a09",
    theme_color: "#0b0a09",
    categories: ["shopping", "lifestyle"],
    lang: info.code,
    dir: info.dir,
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
      { src: "/icons/maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
    shortcuts: [
      { name: t("shop"), url: "/shop?source=pwa", icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }] },
      { name: t("orders"), url: "/account/orders?source=pwa", icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }] },
      { name: t("support"), url: "/account/support?source=pwa", icons: [{ src: "/icons/icon-192.png", sizes: "192x192" }] },
    ],
  };
}
